theme.css:
/* ==== INTERFACE ====
   材质   计算统计手稿与多重决策面叠加：冷岩青中性底配钴蓝基准线与高对比赤赭聚焦点，表现算法的严格正交与重赋权
   token  --bg #F1F4F8            画板背景｜全课冷岩灰底色
   token  --surface #FFFFFF       卡片与图表承载面｜纯白操作面板
   token  --text #16202C          主要正文与坐标轴字｜高对比深冷岩蓝
   token  --muted #627488         次级说明文字、参考线与弱网格｜中明度冷灰
   token  --model #1D5B99         基学习器与常规决策边界｜冷钴蓝
   token  --focus #C93B18         当前焦点、重赋权样本与梯度残差指引｜高警示赤赭色
   token  --ensemble #0B7285      集成模型输出与多样性对比组｜深松石青
   token  --font-sans "Noto Sans CJK SC", "WenQuanYi Zen Hei", sans-serif   投影清晰无衬线体
   token  --font-mono "WenQuanYi Zen Hei Mono", monospace                   代码与矩阵参数等宽体
   token  --fs-h1 34px            页面主标题字号
   token  --fs-h2 22px            结构板块标题字号
   token  --fs-lead 19px          导语与核心设问字号
   token  --fs-body 18px          标准讲解段落正文
   token  --fs-sec 16px           次级说明、注释成句
   token  --fs-label 15px         交互控件、图例与数据轴标签
   token  --fs-tick 13px          坐标系纯数字刻度
   版心   1488×844                #stage 已含 padding
   版式   .focus                  标题后主实验与对比区占满剩余空间
   ==== /INTERFACE ==== */

:root {
  --bg: #F1F4F8;
  --surface: #FFFFFF;
  --text: #16202C;
  --muted: #627488;
  --model: #1D5B99;
  --focus: #C93B18;
  --ensemble: #0B7285;

  --font-sans: "Noto Sans CJK SC", "WenQuanYi Zen Hei", sans-serif;
  --font-mono: "WenQuanYi Zen Hei Mono", monospace;

  --fs-h1: 34px;
  --fs-h2: 22px;
  --fs-lead: 19px;
  --fs-body: 18px;
  --fs-sec: 16px;
  --fs-label: 15px;
  --fs-tick: 13px;

  --pad-x: 56px;
  --pad-y: 28px;
}

body {
  margin: 0;
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--font-sans);
  -webkit-font-smoothing: antialiased;
}

#stage {
  display: flex;
  flex-direction: column;
  padding: var(--pad-y) var(--pad-x);
  box-sizing: border-box;
  width: 1600px;
  height: 900px;
}

.focus {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

svg .bar, svg .cell, svg .box {
  width: auto;
  height: auto;
}
